"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6486],{51086:function(e,s,t){t.d(s,{Z:function(){return l}});var r=t(57437),a=t(2265),n=t(27648),i=t(99376),o=t(40974);function l(e){let{titre:s,texte:t,mot:l,retourHref:c="/v2.1#apps",retourLibelle:u="KAL ecosystem"}=e,d=!s&&!t,p=(0,i.useRouter)(),[f,h]=(0,a.useState)(!1),[m,g]=(0,a.useState)(!1);(0,a.useEffect)(()=>{h(window.history.length>1),g("infos"===window.location.hash.replace(/^#/,""))},[]);let v=m?"/v2.1/#infos":c;return(0,r.jsxs)("div",{className:d?"mb-2":"mb-6 sm:mb-8",children:[v&&(0,r.jsxs)(n.default,{href:v,prefetch:!(0,o.e)(v)&&void 0,onClick:e=>{if(m){e.preventDefault(),window.location.assign("/v2.1/#infos");return}f&&(e.preventDefault(),p.back())},className:"km-v21-retour-ecran inline-flex items-center gap-1.5 text-xs font-semibold text-muted-2 hover:text-[var(--or-texte)] mb-2.5 transition-colors active:scale-95 group",children:[(0,r.jsx)("span",{className:"transition-transform group-hover:-translate-x-0.5 inline-flex",children:(0,r.jsx)("svg",{width:"16",height:"16",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor",strokeWidth:"2",strokeLinecap:"round",strokeLinejoin:"round","aria-hidden":!0,children:(0,r.jsx)("path",{d:"M15 5l-7 7 7 7"})})}),(0,r.jsx)("span",{children:m?"Infos et r\xe9glages":f?"Retour":u})]}),s&&(0,r.jsx)("h1",{className:"text-[calc(var(--km-base)*1.625)] sm:text-[calc(var(--km-base)*1.875)] font-semibold leading-[1.1] tracking-[-0.02em] text-foreground",children:s}),t&&(0,r.jsx)("p",{className:"mt-2 max-w-[50ch] text-[calc(var(--km-base)*0.8125)] leading-relaxed text-muted",children:t})]})}},6486:function(e,s,t){t.r(s),t.d(s,{default:function(){return l}});var r=t(57437),a=t(51086),n=t(94152),i=t(96173);function o(){let{lang:e}=(0,n.Z)();return(0,r.jsx)("div",{className:"space-y-3",children:i.j6.map(s=>(0,r.jsxs)("section",{className:"rounded-[20px] border border-border bg-surface p-4",children:[(0,r.jsx)("h2",{className:"mb-2 text-sm font-bold text-foreground",children:"fr"===e?s.titre.fr:s.titre.en}),(0,r.jsx)("div",{className:"space-y-2",children:s.paragraphes.map((s,t)=>(0,r.jsx)("p",{className:"text-[length:max(11px,calc(var(--km-base)*0.75))] leading-relaxed text-muted",children:"fr"===e?s.fr:s.en},t))})]},s.cle))})}function l(){let{t:e}=(0,n.Z)();return(0,r.jsxs)("div",{className:"space-y-4",children:[(0,r.jsx)(a.Z,{mot:e({fr:"Cadre l\xe9gal",en:"Legal framework"}),titre:e({fr:"Mentions l\xe9gales",en:"Legal notice"})}),(0,r.jsx)(o,{})]})}},96173:function(e,s,t){t.d(s,{Mf:function(){return a},j6:function(){return n}});var r=t(68122);let a={cle:"cgu-kalpay",titre:{fr:"Conditions d’utilisation de KALpay",en:"KALpay terms of use"},paragraphes:[{fr:"1. Objet. KALpay est un logiciel de portefeuille de crypto-actifs non d\xe9positaire \xe9dit\xe9 dans le cadre de l’\xe9cosyst\xe8me Kal Mydas. Il permet \xe0 l’utilisateur de cr\xe9er et d’utiliser une adresse sur la blockchain Base, de conserver ses crypto-actifs, d’effectuer des transferts pair \xe0 pair, d’acqu\xe9rir de l’USDC par carte via un prestataire tiers et d’interagir avec les contrats du protocole. En utilisant KALpay, l’utilisateur accepte les pr\xe9sentes conditions.",en:"1. Purpose: KALpay is a non-custodial crypto-asset wallet software published within the Kal Mydas ecosystem. It lets the user create and use an address on the Base blockchain, hold crypto-assets, make peer to peer transfers, acquire USDC by card through a third party provider, and interact with the protocol contracts. By using KALpay, the user accepts these terms."},{fr:"2. Nature non d\xe9positaire. KALpay est un logiciel. Kal Mydas ne d\xe9tient jamais les cl\xe9s priv\xe9es de l’utilisateur ni ses crypto-actifs ni ses fonds. Kal Mydas n’a aucun acc\xe8s aux avoirs de l’utilisateur et ne peut ni les bloquer ni les d\xe9placer ni les restituer. L’utilisateur est seul d\xe9tenteur et seul responsable de ses cl\xe9s et de ses avoirs.",en:"2. Non-custodial nature: KALpay is software. Kal Mydas never holds the user’s private keys, crypto-assets or funds. Kal Mydas has no access to the user’s holdings and cannot freeze, move or return them. The user is the sole holder and sole party responsible for their keys and holdings."},{fr:"3. Phrase de r\xe9cup\xe9ration, unique moyen de r\xe9cup\xe9ration. \xc0 la cr\xe9ation du portefeuille, une phrase de r\xe9cup\xe9ration de douze mots est pr\xe9sent\xe9e \xe0 l’utilisateur. Cette phrase est le seul moyen de r\xe9cup\xe9rer l’acc\xe8s \xe0 son adresse et \xe0 ses avoirs. L’utilisateur doit la sauvegarder lui-m\xeame, hors ligne, en lieu s\xfbr. En cas de perte de cette phrase, l’acc\xe8s aux avoirs est d\xe9finitivement perdu et Kal Mydas ne peut en aucun cas le r\xe9tablir. Kal Mydas ne conserve aucune copie de cette phrase ni des cl\xe9s.",en:"3. Recovery phrase, the only recovery method: When the wallet is created, a twelve word recovery phrase is shown to the user. This phrase is the only way to recover access to the address and holdings. The user must back it up personally, offline, in a safe place. If this phrase is lost, access to the holdings is permanently lost and Kal Mydas cannot restore it in any way. Kal Mydas keeps no copy of this phrase or of the keys."},{fr:"4. Acc\xe8s au portefeuille et code de d\xe9verrouillage. KALpay ne demande ni compte Google ni adresse de courriel ni aucune identit\xe9 pour \xeatre utilis\xe9. \xc0 la cr\xe9ation, la phrase de douze mots est chiffr\xe9e dans le navigateur de l’utilisateur au moyen d’un code qu’il choisit puis conserv\xe9e sur son seul appareil. Ce code d\xe9verrouille le portefeuille sur cet appareil. Il n’est jamais transmis \xe0 Kal Mydas et ne permet pas de r\xe9cup\xe9rer le portefeuille. Le portefeuille est li\xe9 au navigateur et au site sur lesquels il a \xe9t\xe9 cr\xe9\xe9. Pour l’utiliser ailleurs, l’utilisateur l’importe avec sa phrase de douze mots. L’effacement des donn\xe9es du navigateur supprime le portefeuille de cet appareil. En cas d’oubli du code ou d’effacement, l’acc\xe8s se r\xe9tablit exclusivement par la phrase de douze mots d\xe9crite \xe0 l’article 3.",en:"4. Wallet access and unlock code: KALpay requires no Google account, no email address and no identity of any kind. At creation, the twelve word phrase is encrypted in the user’s browser with a code the user chooses, then kept on that device only. This code unlocks the wallet on that device. It is never sent to Kal Mydas and cannot recover the wallet. The wallet is tied to the browser and the site where it was created: to use it elsewhere, the user imports it with the twelve word phrase. Clearing the browser data removes the wallet from that device. If the code is forgotten or the data is cleared, access is restored exclusively through the twelve word phrase described in article 3."},{fr:"5. Responsabilit\xe9. Kal Mydas n’est pas responsable de la perte des cl\xe9s, de la perte de la phrase de r\xe9cup\xe9ration, des erreurs de manipulation, des pertes de valeur des crypto-actifs ni des cons\xe9quences d’une transaction sign\xe9e par l’utilisateur. L’utilisateur agit sous sa seule responsabilit\xe9.",en:"5. Liability: Kal Mydas is not liable for the loss of keys, the loss of the recovery phrase, handling errors, loss of value of crypto-assets, or the consequences of a transaction signed by the user. The user acts under their sole responsibility."},{fr:"6. Achat par carte, prestataire tiers. L’application propose un lien vers le site du prestataire tiers MoonPay, pour acheter de l’USDC ou de l’ETH sur le r\xe9seau Base, par carte ou par virement. L’achat se fait sur le site du prestataire, hors de l’application. MoonPay Europe B.V. figure au registre MiCA de l’Autorit\xe9 europ\xe9enne des march\xe9s financiers comme prestataire de services sur crypto-actifs agr\xe9\xe9 par l’Autorit\xe9 n\xe9erlandaise des march\xe9s financiers (relev\xe9 du 19 octobre 2026). L’entit\xe9 qui contracte avec l’utilisateur est celle que d\xe9signent les conditions de MoonPay selon son pays de r\xe9sidence. L’utilisateur contracte directement avec ce prestataire. Kal Mydas n’encaisse aucun fonds, n’intervient pas dans le flux de paiement et n’est pas partie \xe0 cette op\xe9ration. Les frais appliqu\xe9s sont ceux du prestataire et des r\xe9seaux de paiement, ind\xe9pendants de Kal Mydas.",en:"6. Card purchase, third party provider: The application offers a link to the website of MoonPay, a third party provider, to buy USDC or ETH on the Base network, by card or bank transfer. The purchase takes place on the provider’s website, outside the application. MoonPay Europe B.V. is listed in the MiCA register of the European Securities and Markets Authority as a crypto-asset service provider authorised by the Dutch Authority for the Financial Markets (register checked on 19 October 2026). The entity contracting with the user is the one designated by MoonPay’s terms according to the user’s country of residence. The user contracts directly with that provider. Kal Mydas receives no funds, does not take part in the payment flow, and is not a party to this transaction. The fees applied are those of the provider and of the payment networks, independent of Kal Mydas."},{fr:"7. Transferts pair \xe0 pair. Les transferts de crypto-actifs sont initi\xe9s, sign\xe9s et diffus\xe9s par l’utilisateur seul, depuis son portefeuille vers une autre adresse. Kal Mydas ne re\xe7oit, ne d\xe9tient et ne transmet jamais les fonds pour le compte de l’utilisateur.",en:"7. Peer to peer transfers: Crypto-asset transfers are initiated, signed and broadcast by the user alone, from their wallet to another address. Kal Mydas never receives, holds or transmits funds on the user’s behalf."},{fr:"8. Interactions avec le protocole. L’utilisateur peut interagir avec les contrats du protocole, y compris pour apporter de la liquidit\xe9 ou verrouiller des jetons. Chaque interaction r\xe9sulte d’une signature explicite de l’utilisateur. Kal Mydas n’exerce aucune gestion discr\xe9tionnaire des avoirs de l’utilisateur et ne fournit aucun conseil en investissement.",en:"8. Protocol interactions: The user may interact with the protocol contracts, including to provide liquidity or lock tokens. Each interaction results from an explicit signature by the user. Kal Mydas exercises no discretionary management of the user’s holdings and provides no investment advice."},{fr:"9. Absence de conseil et de promesse. KALpay ne fournit aucun conseil financier, fiscal ou juridique. Aucune promesse de performance ni de gain n’est faite. La valeur des crypto-actifs peut varier fortement. Les crypto-actifs comportent un risque de perte partielle ou totale du capital.",en:"9. No advice, no promise: KALpay provides no financial, tax or legal advice. No promise of performance or gain is made. The value of crypto-assets can vary sharply. Crypto-assets carry a risk of partial or total loss of capital."},{fr:"10. Juridictions exclues. KALpay n’est pas accessible depuis les pays sous sanctions internationales, la Cor\xe9e du Nord, Iran, Syrie, Cuba, Russie, Bi\xe9lorussie. L’utilisateur s’engage \xe0 ne pas utiliser le service depuis ces pays ni \xe0 contourner les mesures de restriction g\xe9ographique. Les \xc9tats-Unis et le Royaume-Uni ne figurent pas dans cette liste. Kal Mydas n’y propose pas le service, n’y ach\xe8te aucune publicit\xe9 et n’y contacte personne. Les personnes qui s’y connectent acc\xe8dent au service de leur propre initiative apr\xe8s avoir coch\xe9 une d\xe9claration en ce sens. Il leur revient de v\xe9rifier ce que leur droit permet.",en:"10. Excluded jurisdictions: KALpay is not accessible from countries under international sanctions: North Korea, Iran, Syria, Cuba, Russia, Belarus. The user undertakes not to use the service from these countries or to circumvent the geographic restriction measures. The United States and the United Kingdom are not on this list. Kal Mydas does not offer the service there, buys no advertising there and contacts no one there. People who connect from these countries access the service on their own initiative, after ticking a declaration to that effect. It is up to them to check what their law allows."},{fr:"11. Logiciel fourni en l’\xe9tat. Le logiciel est fourni en l’\xe9tat, sans garantie d’aucune sorte, expresse ou implicite, notamment d’ad\xe9quation \xe0 un usage particulier ou d’absence de d\xe9faut. L’utilisateur reconna\xeet utiliser un logiciel exp\xe9rimental \xe0 ses propres risques.",en:"11. Software provided as is: The software is provided as is, without warranty of any kind, express or implied, including fitness for a particular purpose or absence of defect. The user acknowledges using experimental software at their own risk."},{fr:"12. Capacit\xe9. L’utilisateur d\xe9clare \xeatre majeur et juridiquement capable dans sa juridiction de r\xe9sidence.",en:"12. Capacity: The user declares being of legal age and legally capable in their jurisdiction of residence."},{fr:"13. Droit applicable et for. Les pr\xe9sentes conditions sont r\xe9gies par le droit suisse. Tout litige rel\xe8ve des tribunaux comp\xe9tents du si\xe8ge de l’entit\xe9 \xe9ditrice. La d\xe9signation pr\xe9cise de l’entit\xe9 et de son si\xe8ge sera compl\xe9t\xe9e \xe0 la constitution de la structure juridique du projet.",en:"13. Governing law and jurisdiction: These terms are governed by Swiss law. Any dispute falls under the competent courts of the registered seat of the publishing entity. The precise designation of the entity and its seat will be completed upon incorporation of the project’s legal structure."},{fr:"14. \xc9volution des conditions. Kal Mydas peut faire \xe9voluer les pr\xe9sentes conditions. La version en vigueur est celle publi\xe9e dans l’application au moment de l’utilisation.",en:"14. Changes to the terms: Kal Mydas may change these terms. The version in force is the one published in the application at the time of use."}]},n=[{cle:"nature",titre:{fr:"Nature de l’interface",en:"Nature of the interface"},paragraphes:[{fr:"home.kalmydas.com est une interface non d\xe9positaire. Elle vous permet d’agir directement avec les contrats intelligents du protocole KAL d\xe9ploy\xe9s sur Base, couche 2 d’Ethereum. Vos actifs restent dans votre portefeuille jusqu’\xe0 la signature de chaque transaction. Une fois d\xe9pos\xe9s, ils sont tenus par le contrat du pool et non par une personne.",en:"home.kalmydas.com is a non-custodial interface. It lets you act directly with the KAL protocol smart contracts deployed on Base, an Ethereum layer 2. Your assets remain in your wallet until you sign each transaction. Once deposited, they are held by the pool contract and not by a person."},{fr:"Le protocole KAL est un ensemble de contrats d\xe9ploy\xe9s sur Base, au code source lisible sur Basescan. Il comprend des strat\xe9gies algorithmiques, un march\xe9 du KAL, des r\xe9serves de liquidit\xe9, le verrouillage en veKAL et un Pass d’acc\xe8s.",en:"The KAL protocol is a set of contracts deployed on Base, with source code readable on Basescan. It includes algorithmic strategies, a KAL market, liquidity pools, veKAL locking and an access Pass."},{fr:"Cette interface ne constitue ni un conseil financier ni une sollicitation ni une offre de valeurs mobili\xe8res au sens de la LSFin (Suisse) ou de MiFID II (UE). KAL est un jeton utilitaire ERC-20, pas une valeur mobili\xe8re.",en:"This interface does not constitute financial advice, solicitation, or a securities offering under Swiss LSFin or EU MiFID II. KAL is an ERC-20 utility token, not a security."},{fr:"Toute offre de jetons KAL dans l’Union europ\xe9enne se fait au titre de l’exemption pr\xe9vue par l’article 4(2) du r\xe8glement UE 2023/1114 sur les march\xe9s de crypto-actifs (MiCA). Aucun livre blanc crypto-actifs n’est publi\xe9 et aucune offre n’a \xe9t\xe9 approuv\xe9e par une autorit\xe9. Cette interface ne propose aucune vente de jetons KAL. Le cadre r\xe9glementaire complet est publi\xe9 sur docs.kalmydas.com/regulation-ue.",en:"Any offering of KAL tokens in the European Union falls under the exemption set out in Article 4(2) of EU Regulation 2023/1114 on Markets in Crypto-Assets (MiCA). No crypto-asset white paper is published, and no offering has been approved by any authority. This interface does not offer any sale of KAL tokens. The full regulatory framework is published at docs.kalmydas.com/regulation-ue."}]},{cle:"conditions",titre:{fr:"Conditions d’utilisation",en:"Terms of use"},paragraphes:[{fr:"En acc\xe9dant \xe0 cette interface, vous acceptez l’int\xe9gralit\xe9 des conditions g\xe9n\xe9rales d’utilisation du protocole KAL, articles 1 \xe0 15, publi\xe9es sur docs.kalmydas.com/legal#conditions. Cette section n’en pr\xe9sente qu’un r\xe9sum\xe9.",en:"By accessing this interface, you accept the full Terms of Service of the KAL protocol, articles 1 to 15, published at docs.kalmydas.com/legal#conditions. This section is only a summary."},{fr:"Pour utiliser cette interface, vous devez \xeatre \xe2g\xe9 d’au moins 18 ans, ne pas r\xe9sider dans une juridiction sous sanctions internationales (Cor\xe9e du Nord, Iran, Syrie, Cuba, Russie, Bi\xe9lorussie), ne pas \xeatre une personne politiquement expos\xe9e sous sanctions, respecter les lois fiscales et r\xe9glementaires de votre pays et avoir la capacit\xe9 juridique de conclure un contrat.",en:"To use this interface, you must: be at least 18 years old, not reside in a jurisdiction under international sanctions (North Korea, Iran, Syria, Cuba, Russia, Belarus), not be a politically exposed person under sanctions, comply with the tax and regulatory laws of your country, have the legal capacity to enter into a contract."},{fr:"Vous \xeates seul responsable de la s\xe9curit\xe9 de votre portefeuille, de vos cl\xe9s priv\xe9es et de vos d\xe9cisions. La perte d’acc\xe8s \xe0 votre portefeuille entra\xeene la perte d\xe9finitive des actifs d\xe9pos\xe9s. Le service est fourni \xab\xa0en l’\xe9tat\xa0\xbb sans garantie. Kal Mydas ne sera en aucun cas responsable des pertes financi\xe8res directes ou indirectes.",en:"You are solely responsible for the security of your wallet, your private keys and your decisions. Losing access to your wallet results in the permanent loss of deposited assets. The service is provided \xab as-is \xbb without warranty. Kal Mydas shall not be liable for any direct or indirect financial losses."}]},{cle:"risques",titre:{fr:"Avertissement sur les risques",en:"Risk warning"},paragraphes:[{fr:"Avertissement. Utiliser le protocole KAL comporte un risque \xe9lev\xe9 pouvant aller jusqu’\xe0 la perte totale (100 %) du capital d\xe9pos\xe9. Les performances pass\xe9es ne pr\xe9jugent pas des performances futures. Les simulations affich\xe9es ne constituent ni une promesse ni une garantie ni une pr\xe9diction.",en:"WARNING: using the KAL protocol carries a high risk including total loss (100%) of deposited capital. Past performance does not guarantee future results. The simulations shown do not constitute a promise, guarantee or prediction."},{fr:"Les risques principaux \xe0 conna\xeetre sont la volatilit\xe9 du march\xe9 de l’or (XAUUSD), des baisses pouvant exc\xe9der 50\xa0% sur les strat\xe9gies agressives (TREASURY, ORION), le risque de bug ou de vuln\xe9rabilit\xe9 dans les contrats intelligents malgr\xe9 les revues de s\xe9curit\xe9 conduites en interne et en audit externe ind\xe9pendant, la perte impermanente sur les pools de liquidit\xe9, le risque oracle (Chainlink), le risque de s\xe9quenceur Base (rollup optimiste), le risque r\xe9glementaire \xe9volutif et le risque op\xe9rationnel li\xe9 au robot ex\xe9cuteur des strat\xe9gies algorithmiques.",en:"Main risks to be aware of: gold market (XAUUSD) volatility, drawdowns potentially exceeding 50% on aggressive strategies (TREASURY, ORION), risk of bugs or vulnerabilities in smart contracts despite security reviews conducted in house and by independent external audits, impermanent loss on liquidity pools, oracle risk (Chainlink), Base sequencer risk (optimistic rollup), evolving regulatory risk, operational risk related to the bot executing algorithmic strategies."},{fr:"La liste compl\xe8te des 13 risques d\xe9taill\xe9s (march\xe9, algorithmique, contrat intelligent, technique, liquidit\xe9, perte impermanente, r\xe9glementaire, infrastructure, oracle, d\xe9pendance Base, personne cl\xe9, absence de conseil, ex\xe9cution) est publi\xe9e sur docs.kalmydas.com/legal#risques. Vous reconnaissez en avoir pris connaissance avant toute interaction.",en:"The full list of 13 detailed risks (market, algorithmic, smart contract, technical, liquidity, impermanent loss, regulatory, infrastructure, oracle, Base dependency, key person, no financial advice, execution) is published at docs.kalmydas.com/legal#risques. You acknowledge having read it before any interaction."},{fr:"R\xe9partition de la perte. Le collat\xe9ral des positions vient du capital propre du protocole. Il ne vient pas de votre d\xe9p\xf4t. La perte est r\xe9partie entre ce capital et les d\xe9p\xf4ts, chacun au prorata de son poids dans la r\xe9serve. Votre d\xe9p\xf4t est donc d\xe9bit\xe9 d’une part de chaque perte, alors m\xeame que vous n’avez financ\xe9 aucun collat\xe9ral. Cette part n’est pas fixe. Rien ne borne le cumul de ces pertes dans le temps. Votre capital d\xe9pos\xe9 peut \xeatre entam\xe9 en totalit\xe9.",en:"Loss allocation. The collateral behind the positions comes from the protocol's own capital. It does not come from your deposit. The loss is split between that capital and the deposits, each in proportion to its weight in the pool. Your deposit is therefore debited a share of every loss, even though you funded no collateral. That share is not fixed. Nothing bounds the sum of those losses over time. Your deposited capital can be eaten into entirely."}]},{cle:"frais",titre:{fr:"Frais du protocole",en:"Protocol fees"},paragraphes:[{fr:"Frais sur d\xe9p\xf4t et retrait \xe0 0 %, seuls les frais de r\xe9seau Base s’appliquent, g\xe9n\xe9ralement quelques centimes. Pas de frais d’inactivit\xe9, de maintenance ou de fermeture.",en:"Deposit and withdrawal fees: 0% (only Base gas fees apply, usually a few cents). No inactivity, maintenance or closure fees."},{fr:"Frais sur r\xe9sultats, per\xe7us uniquement sur les gains r\xe9alis\xe9s selon le principe du plus haut historique, de 20\xa0% sur chaque strat\xe9gie et de 10\xa0% pour un d\xe9p\xf4t en KAL. Aucun frais de gestion n’est pr\xe9lev\xe9 aujourd’hui. Le contrat pr\xe9voit ce pr\xe9l\xe8vement mensuel et le plafonne \xe0 5 % par mois. \xc9change (KalSwap, KalSwapETH) \xe0 0,3 % par transaction. Pass d’acc\xe8s de 1,00 \xe0 5,00 USDC par jour selon le niveau (Bronze 1,00, Argent 1,50, Or 2,50, Diamant 5,00). La dur\xe9e choisie donne une remise de 10 % \xe0 30 % \xe0 partir de 7 jours (7 jours 10 %, 30 jours 15 %, 90 jours 20 %, 180 jours 25 %, 365 jours 30 %) et le paiement en KAL une remise suppl\xe9mentaire de 30 %.",en:"Performance fees (charged only on realized gains, High-Water Mark principle): 20% on every strategy and 10% for a KAL deposit. No management fee is charged today. The contract provides for this monthly charge and caps it at 5% per month. Exchange (KalSwap, KalSwapETH): 0.3% per trade. Access Pass NFT: from 1.00 to 5.00 USDC per day depending on the level (Bronze 1.00, Silver 1.50, Gold 2.50, Diamond 5.00). The chosen duration gives a 10% to 30% discount from 7 days onwards (7 days 10%, 30 days 15%, 90 days 20%, 180 days 25%, 365 days 30%), and paying in KAL a further 30% discount."},{fr:"L’int\xe9gralit\xe9 des frais est inscrite dans les contrats intelligents et publiquement v\xe9rifiable sur Basescan. La r\xe9partition des frais entre r\xe9serve du protocole, rachat de KAL redirig\xe9 vers la liquidit\xe9 du protocole (doctrine Zero Burn, le KAL n’est jamais br\xfbl\xe9), LP, veKAL, fondateur et tr\xe9sorerie RWA est d\xe9taill\xe9e sur docs.kalmydas.com/legal#frais.",en:"All fees are encoded in the smart contracts and publicly verifiable on Basescan. The fee distribution between protocol reserve, KAL buyback redirected to protocol liquidity (Zero Burn doctrine, KAL is never burned), LP, veKAL, founder and RWA treasury is detailed at docs.kalmydas.com/legal#frais."}]},{cle:"confidentialite",titre:{fr:"Confidentialit\xe9",en:"Privacy"},paragraphes:[{fr:"Cette interface est conforme au RGPD (UE) et \xe0 la nLPD (Suisse). Le responsable du traitement est Kal Mydas, kal@kalmydas.ch, juridiction Suisse.",en:"This interface complies with the GDPR (EU) and nLPD (Switzerland). Data Controller: Kal Mydas, kal@kalmydas.ch, Swiss jurisdiction."},{fr:"L’interface traite l’adresse de portefeuille (publique, pseudonymis\xe9e au sens du RGPD), vos pr\xe9f\xe9rences d’affichage, votre choix de consentement et des journaux techniques anonymis\xe9s. Si vous l’acceptez, une mesure d’audience sans cookie, Umami, compte les visites de fa\xe7on agr\xe9g\xe9e. Si vous cr\xe9ez un coffre KALpay, il reste chiffr\xe9 dans votre navigateur et n’est jamais transmis. Les interactions sur la cha\xeene sont publiques et permanentes par nature de la blockchain Base. Elles ne sont pas \xab collect\xe9es \xbb par Kal Mydas mais accessibles librement sur Basescan.",en:"Data processed by the interface: wallet address (public, pseudonymized under GDPR), your display preferences, your consent choice, and anonymized technical logs. If you accept it, a cookieless audience measurement, Umami, counts visits in aggregate. If you create a KALpay vault, it stays encrypted in your browser and is never transmitted. On-chain interactions are public and permanent by the nature of the Base blockchain; they are not \xab collected \xbb by Kal Mydas but freely accessible on Basescan."},{fr:"Vos droits (acc\xe8s, rectification, effacement hors on-chain, opposition, portabilit\xe9, retrait du consentement) s’exercent par courriel \xe0 kal@kalmydas.ch. Vous pouvez introduire une r\xe9clamation aupr\xe8s de la CNIL (France) ou du PFPDT (Suisse). Politique compl\xe8te, finalit\xe9s, dur\xe9es de conservation et destinataires sur docs.kalmydas.com/legal#confidentialite.",en:"Your rights (access, rectification, erasure except on-chain, objection, portability, withdrawal of consent) can be exercised by email at kal@kalmydas.ch. You may file a complaint with the CNIL (France) or PFPDT (Switzerland). Full policy, purposes, retention periods and recipients at docs.kalmydas.com/legal#confidentialite."}]},{cle:"cookies",titre:{fr:"Cookies",en:"Cookies"},paragraphes:[{fr:"Cette interface d\xe9pose quatre cookies de pr\xe9f\xe9rence, strictement n\xe9cessaires, gard\xe9s 12 mois. km_lang retient la langue, km_theme le th\xe8me, km_mode le mode d’affichage et km_devise la devise. Votre choix de consentement reste dans votre navigateur. Si vous l’acceptez, une mesure d’audience sans cookie, Umami, compte les visites de fa\xe7on agr\xe9g\xe9e. Aucun cookie publicitaire n’est d\xe9pos\xe9.",en:"This interface sets four preference cookies, strictly necessary, kept for 12 months: km_lang keeps the language, km_theme the theme, km_mode the display mode and km_devise the currency. Your consent choice stays in your browser. If you accept it, a cookieless audience measurement, Umami, counts visits in aggregate. No advertising cookie is set."},{fr:"Vous pouvez bloquer tous les cookies depuis votre navigateur ou supprimer les cookies existants. Sans eux, l’interface oublie seulement vos pr\xe9f\xe9rences.",en:"You can block all cookies from your browser or delete existing cookies. Without them, the interface only forgets your preferences."},{fr:"Les cookies des sites tiers, X, Telegram ou Discord, ne s’appliquent que si vous ouvrez leurs liens. D\xe9tail sur docs.kalmydas.com/legal#cookies.",en:"Third-party site cookies, X, Telegram or Discord, only apply if you open their links. Details at docs.kalmydas.com/legal#cookies."}]},{cle:"espace-discussion",titre:{fr:"Espace de discussion KALchat",en:"KALchat discussion space"},paragraphes:[...r.hP.fr.slice(1).map((e,s)=>({fr:e,en:r.hP.en[s+1]})),r.E4,r.xY]},a]},68122:function(e,s,t){function r(e,s){return"en"===s?e.en:e.fr}t.d(s,{E4:function(){return a},Hh:function(){return u},Iy:function(){return c},T:function(){return l},hP:function(){return i},r6:function(){return o},tr:function(){return r},xY:function(){return n}});let a={fr:"Les messages de cet espace sont publi\xe9s par leurs auteurs sur un r\xe9seau de messagerie d\xe9centralis\xe9 tiers. Ils n’engagent pas le protocole et ne constituent ni un conseil ni une offre. Aucun chiffre de performance cit\xe9 par un membre n’est v\xe9rifi\xe9 par le protocole.",en:"Messages in this space are published by their authors on a third-party decentralised messaging network. They do not bind the protocol and constitute neither advice, nor an offer. No performance figure mentioned by a member is verified by the protocol."},n={fr:"Rappel. Toute performance des strat\xe9gies repose sur des simulations historiques sur 4 \xe0 21 ans de donn\xe9es XAUUSD. L’ex\xe9cution r\xe9elle via gTrade peut produire des r\xe9sultats diff\xe9rents. Risque de perte partielle ou totale du capital. Les performances pass\xe9es ne garantissent pas les performances futures.",en:"Reminder. Any performance of the strategies rests on historical simulations over 4 to 21 years of XAUUSD data. Live execution via gTrade may produce different results. Risk of partial or total capital loss. Past performance does not guarantee future results."},i={fr:["Charte de l’espace de discussion.","Cet espace est ouvert \xe0 toute personne qui a un compte connect\xe9. Le canal des annonces se lit sans Pass, les salons de discussion demandent un Pass d’acc\xe8s actif. Il sert la d\xe9couverte et l’usage des strat\xe9gies. Les \xe9changes se font entre membres et n’engagent pas le protocole.","Sont interdits dans cet espace, les contenus illicites, la sollicitation financi\xe8re sous toute forme, le conseil en investissement au sens r\xe9glementaire, la promotion de projets ou de services de tiers, les propos qui portent atteinte aux personnes et toute forme de harc\xe8lement ou de courrier ind\xe9sirable.","Les messages publi\xe9s par les membres ne constituent ni un conseil ni une recommandation ni une offre du protocole. Aucun chiffre de performance mentionn\xe9 par un membre n’est v\xe9rifi\xe9 par le protocole.","Le protocole peut suspendre l’acc\xe8s d’un portefeuille \xe0 l’espace de discussion en cas de violation de la pr\xe9sente charte. Les messages vivent sur un r\xe9seau d\xe9centralis\xe9 tiers, le protocole ne peut pas les supprimer de ce r\xe9seau.","Un point de contact est mis \xe0 disposition pour signaler un contenu. Un signalement est trait\xe9 au niveau de l’acc\xe8s \xe0 l’espace.","La pr\xe9sente charte est opposable. Entrer dans l’espace de discussion vaut acceptation de ces r\xe8gles d’usage."],en:["Charter of the discussion space.","This space is open to anyone with a connected account. The announcements channel is read without a Pass, the discussion rooms require an active access Pass. It supports discovering and using the strategies. Exchanges take place between members and do not bind the protocol.","The following are prohibited in this space, unlawful content, financial solicitation in any form, investment advice within the regulatory meaning, promotion of third-party projects or services, statements harmful to individuals, and any form of harassment or spam.","Messages published by members constitute neither advice, nor a recommendation, nor an offer from the protocol. No performance figure mentioned by a member is verified by the protocol.","The protocol may suspend a wallet's access to the discussion space in the event of a breach of this charter. Messages live on a third-party decentralised network; the protocol cannot delete them from that network.","A contact point is provided to report content. A report is handled at the level of access to the space.","This charter is enforceable. Entering the discussion space constitutes acceptance of these usage rules."]},o=[{url:"https://docs.kalmydas.com/espace-discussion-legal",titre:{fr:"Espace de discussion \xb7 textes juridiques",en:"Discussion space: legal texts"}},{url:"https://docs.kalmydas.com/reglement-quetes-avenant-chat",titre:{fr:"Avenant au r\xe8glement du programme de qu\xeates",en:"Amendment to the Quest Program Rules"}}],l={espaceFerme:{fr:"Cet espace n’est pas encore ouvert. Il le sera \xe0 l’ouverture publique.",en:"This space is not open yet. It will open at the public launch."},ongletDejaOuvert:{fr:"La messagerie est d\xe9j\xe0 ouverte dans un autre onglet. Pour pr\xe9server votre session et vos messages, un seul onglet de la discussion peut rester actif. Fermez les autres onglets puis rechargez cette page.",en:"The messaging service is already open in another tab. To preserve your session and your messages, only one discussion tab can stay active. Close the other tabs, then reload this page."},ongletDejaOuvertCourt:{fr:"La messagerie est d\xe9j\xe0 ouverte dans un autre onglet. Fermez les autres onglets puis r\xe9essayez.",en:"The messaging service is already open in another tab. Close the other tabs, then try again."},connectezPortefeuille:{fr:"Connectez votre portefeuille pour continuer.",en:"Connect your wallet to continue."},connexion:{fr:"Connexion",en:"Connect"},accesReserveTitre:{fr:"Acc\xe8s r\xe9serv\xe9",en:"Restricted access"},accesReserveTexte:{fr:"Cet espace n’est pas encore ouvert pour ce portefeuille.",en:"This space is not open yet for this wallet."},verificationPass:{fr:"V\xe9rification de votre Pass...",en:"Checking your Pass..."},passRequisTitre:{fr:"Pass requis",en:"Pass required"},passRequisTexte:{fr:"L’acc\xe8s aux salons requiert un Pass d’acc\xe8s valide sur ce portefeuille.",en:"Access to the rooms requires a valid Access Pass on this wallet."},etablirIdentite:{fr:"\xc9tablir l’identit\xe9 de messagerie",en:"Set up the messaging identity"},etablissementEnCours:{fr:"\xc9tablissement de l’identit\xe9…",en:"Setting up the identity…"},signatureExplication:{fr:"Une signature vous sera demand\xe9e dans votre portefeuille. Elle d\xe9rive votre identit\xe9 de messagerie et n’engage aucune d\xe9pense.",en:"A signature will be requested in your wallet. It derives your messaging identity and involves no spending."},connexionEchouee:{fr:"La connexion n’a pas abouti :",en:"The connection did not go through:"},repriseEnCours:{fr:"Reprise de votre identit\xe9 de messagerie sur cet appareil. Aucune signature n’est demand\xe9e.",en:"Resuming your messaging identity on this device. No signature is requested."},repriseEchouee:{fr:"Votre identit\xe9 de messagerie n’a pas pu \xeatre reprise sur cet appareil.",en:"Your messaging identity could not be resumed on this device."},repriseMotifTechnique:{fr:"Motif technique :",en:"Technical reason:"},stockageRefuse:{fr:"Le navigateur a refus\xe9 le stockage persistant. La base locale peut \xeatre effac\xe9e entre deux visites.",en:"The browser refused persistent storage. The local base may be cleared between visits."},placesTitre:{fr:"Vos places d’appareils",en:"Your device slots"},placesTexte:{fr:"Le r\xe9seau de messagerie accorde dix places par identit\xe9. Une place est prise \xe0 vie tant qu’elle n’est pas lib\xe9r\xe9e.",en:"The messaging network grants ten slots per identity. A slot stays taken until it is freed."},placesInconnues:{fr:"Le nombre de places prises n’a pas pu \xeatre lu.",en:"The number of slots taken could not be read."},placesRestantesZero:{fr:"Vos dix places sont prises. Lib\xe9rez des appareils avant d’en \xe9tablir une de plus.",en:"Your ten slots are taken. Free up devices before setting up one more."},coutDuGeste:{fr:"\xc9tablir une identit\xe9 sur cet appareil prend une place de plus et cette place ne se rend pas toute seule.",en:"Setting up an identity on this device takes one more slot, and that slot does not come back on its own."},confirmerBouton:{fr:"Confirmer et prendre une place",en:"Confirm and take a slot"},annulerBouton:{fr:"Annuler",en:"Cancel"},libererTitre:{fr:"Lib\xe9rer vos appareils",en:"Free up your devices"},libererTexte:{fr:"Le r\xe9seau de messagerie autorise 10 appareils par identit\xe9. Chaque navigateur, chaque adresse de site et chaque effacement de donn\xe9es locales en occupe un. Lib\xe9rer les places retire l’acc\xe8s \xe0 tous vos appareils enregistr\xe9s, celui-ci compris. Chacun redemandera une signature \xe0 sa prochaine visite. Vos salons et vos messages restent sur le r\xe9seau, ils reviennent \xe0 la reconnexion.",en:"The messaging network allows 10 devices per identity. Every browser, every site address and every clearing of local data takes up one. Freeing the slots removes access from all your registered devices, including this one. Each will request a signature again on its next visit. Your rooms and your messages stay on the network, they come back when you reconnect."},libererBouton:{fr:"Lib\xe9rer mes appareils",en:"Free up my devices"},liberationEnCours:{fr:"Lib\xe9ration en cours…",en:"Freeing up…"},signatureSansDepense:{fr:"Une signature vous sera demand\xe9e. Elle n’engage aucune d\xe9pense.",en:"A signature will be requested. It involves no spending."},reseauXmtp:{fr:"R\xe9seau XMTP",en:"XMTP network"},vosSalons:{fr:"Vos salons.",en:"Your rooms."},modeTestLocal:{fr:"Mode test local, connexion directe MetaMask, Pass lu sur Base.",en:"Local test mode: direct MetaMask connection, Pass read on Base."},salons:{fr:"Salons",en:"Rooms"},toutPassValide:{fr:"Tout Pass valide",en:"Any valid Pass"},choisirSalon:{fr:"Choisissez un salon pour commencer.",en:"Choose a room to begin."},quitter:{fr:"Quitter",en:"Leave"},pointsTitre:{fr:"Points d’exp\xe9rience de la discussion",en:"Discussion experience points"},plafondSemaine:{fr:"Cette semaine",en:"This week"},cumules:{fr:"Cumul\xe9s",en:"Accrued"},convertibles:{fr:"Convertibles",en:"Convertible"},joursDePass:{fr:"Jours de Pass",en:"Pass days"},demandeEnregistree:{fr:"Demande enregistr\xe9e",en:"Request recorded"},plafondSemaineTexte:{fr:"Jusqu’\xe0 50 points d’exp\xe9rience peuvent \xeatre attribu\xe9s par semaine calendaire, \xe0 l’appr\xe9ciation du protocole. Une contribution n’ouvre aucun droit acquis \xe0 ce forfait.",en:"Up to fifty experience points may be allocated per calendar week, at the protocol’s discretion. A contribution gives rise to no vested right to this allowance."},pointsSansValeur:{fr:"Les points n’ont aucune valeur mon\xe9taire. La prolongation est accord\xe9e par le fondateur, sans flux de jeton.",en:"The points have no monetary value. The extension is granted by the founder, with no token flow."},conversionUlterieure:{fr:"La conversion des points en jours de Pass sera ouverte ult\xe9rieurement. Vos points continuent de s’accumuler.",en:"Converting points into Pass days will open later. Your points keep accruing."},reglesTitre:{fr:"R\xe8gles du salon et informations",en:"Room rules and information"},afficher:{fr:"Afficher",en:"Show"},masquer:{fr:"Masquer",en:"Hide"},charteTitre:{fr:"Charte de salon",en:"Room charter"},pointsExperienceTitre:{fr:"Points d’exp\xe9rience",en:"Experience points"},pointsExperienceTexte:{fr:"La participation peut cr\xe9er des points d’exp\xe9rience, convertibles en jours de Pass. Ces points n’ont aucune valeur mon\xe9taire, ne sont ni un jeton ni un gain et ne peuvent \xeatre ni vendus ni transf\xe9r\xe9s.",en:"Participation may create experience points, convertible into Pass days. These points have no monetary value, are neither a token nor a gain, and can be neither sold nor transferred."},confidentialiteTitre:{fr:"Confidentialit\xe9",en:"Privacy"},confidentialiteTexte:{fr:"La messagerie s’appuie sur un r\xe9seau tiers d\xe9centralis\xe9 (XMTP). Les messages y sont publi\xe9s hors de l’application. Le retrait de l’acc\xe8s au niveau de l’application n’efface pas les messages d\xe9j\xe0 publi\xe9s sur ce r\xe9seau. Le d\xe9compte des points d’exp\xe9rience est tenu localement sur votre appareil, associ\xe9 \xe0 l’adresse de votre portefeuille et destin\xe9 \xe0 \xeatre repris par un registre s\xe9curis\xe9.",en:"The messaging service relies on a third-party decentralised network (XMTP). Messages are published there, outside the application. Removing access at the application level does not erase messages already published on that network. The experience point tally is kept locally on your device, tied to your wallet address, and intended to be taken over by a secured register."},rappelBasDePage:{fr:"La messagerie s’appuie sur un r\xe9seau tiers d\xe9centralis\xe9 (XMTP). Le retrait de l’acc\xe8s au niveau de l’application n’efface pas les messages d\xe9j\xe0 publi\xe9s sur ce r\xe9seau tiers. Les \xe9changes ne constituent ni un conseil ni une sollicitation ni une promesse de r\xe9sultat.",en:"The messaging service relies on a third-party decentralised network (XMTP). Removing access at the application level does not erase messages already published on that third-party network. The exchanges constitute neither advice, nor a solicitation, nor a promise of result."},textesComplets:{fr:"Textes juridiques complets, sur la documentation",en:"Full legal texts, on the documentation"},chargementMessages:{fr:"Chargement des messages…",en:"Loading messages…"},aucunMessage:{fr:"Aucun message pour l’instant. Ouvrez la conversation.",en:"No message yet. Open the conversation."},vous:{fr:"Vous",en:"You"},anonyme:{fr:"anonyme",en:"anonymous"},signaler:{fr:"Signaler",en:"Report"},messageSignale:{fr:"Message signal\xe9",en:"Message reported"},signalementEnvoi:{fr:"Envoi…",en:"Sending…"},signalementAccuse:{fr:"Re\xe7u, n\xb0",en:"Received, no."},ouvrirSalonPourEcrire:{fr:"Ouvrez un salon pour \xe9crire",en:"Open a room to write"},votreMessage:{fr:"Votre message",en:"Your message"},envoyer:{fr:"Envoyer",en:"Send"},envoiEnCours:{fr:"Envoi…",en:"Sending…"},aideClavier:{fr:"Entr\xe9e pour envoyer, Maj plus Entr\xe9e pour un saut de ligne.",en:"Enter to send, Shift plus Enter for a line break."},aucunMetaMask:{fr:"Aucun portefeuille MetaMask d\xe9tect\xe9.",en:"No MetaMask wallet detected."},portefeuilleIndisponible:{fr:"Portefeuille indisponible.",en:"Wallet unavailable."},erreurInconnue:{fr:"Erreur inconnue.",en:"Unknown error."},quotaAppareils:{fr:"votre identit\xe9 de messagerie est d\xe9j\xe0 port\xe9e par 10 appareils, le maximum autoris\xe9 par le r\xe9seau.",en:"your messaging identity is already carried by 10 devices, the maximum the network allows."},ouvertureSalonImpossible:{fr:"Ouverture du salon impossible.",en:"The room could not be opened."},envoiImpossible:{fr:"Envoi impossible.",en:"The message could not be sent."},liberationEchouee:{fr:"La lib\xe9ration n’a pas abouti.",en:"Freeing up did not go through."},journalAfficher:{fr:"Afficher le journal de session",en:"Show the session log"},journalTitre:{fr:"Journal de reprise",en:"Session resume log"},journalVide:{fr:"Aucune ligne pour cette adresse sur cet appareil.",en:"No entry for this address on this device."},journalCopier:{fr:"Copier le journal",en:"Copy the log"},journalCopie:{fr:"Journal copi\xe9.",en:"Log copied."},salonIndisponibleTitre:{fr:"Ce salon ne s’ouvre pas sur cet appareil",en:"This room will not open on this device"},salonIndisponibleTexte:{fr:"La liaison entre cet appareil et le salon n’a pas pu \xeatre \xe9tablie. Votre historique reste sur le r\xe9seau, rien n’est perdu. Vous pouvez r\xe9essayer ; il n’est pas utile d’\xe9tablir une nouvelle identit\xe9, cela ne r\xe9tablirait pas la liaison.",en:"The link between this device and the room could not be established. Your history stays on the network, nothing is lost. You may try again; setting up a new identity would not restore the link."},salonReessayer:{fr:"R\xe9essayer",en:"Try again"},salonMotifTechnique:{fr:"Motif technique :",en:"Technical reason:"},lecturePassImpossible:{fr:"Lecture du Pass impossible. V\xe9rifiez que votre portefeuille est sur le r\xe9seau Base.",en:"The Pass could not be read. Check that your wallet is on the Base network."},panneauTitre:{fr:"Espace de discussion",en:"Discussion space"},panneauFermer:{fr:"Fermer le panneau",en:"Close the panel"},panneauPageEntiere:{fr:"Page enti\xe8re",en:"Full page"},panneauRetourSalons:{fr:"Retour aux salons",en:"Back to the rooms"},panneauResteSurPage:{fr:"Le journal de reprise et le d\xe9tail des points d’exp\xe9rience se lisent sur la page enti\xe8re.",en:"The session resume log and the detail of experience points are read on the full page."},canalAnnoncesOuvrir:{fr:"Ouvrir le canal des annonces",en:"Open the announcements channel"}},c={0:{fr:"Bronze",en:"Bronze"},1:{fr:"Argent",en:"Silver"},2:{fr:"Or",en:"Gold"},3:{fr:"Diamant",en:"Diamond"}},u={accueil:{nom:{fr:"Accueil",en:"Welcome"},desc:{fr:"Le salon commun \xe0 tous les d\xe9tenteurs d’un Pass valide. Pr\xe9sentations, entraide, premi\xe8res questions.",en:"The room shared by all holders of a valid Pass. Introductions, peer support, first questions."}},strategies:{nom:{fr:"Strat\xe9gies",en:"Strategies"},desc:{fr:"\xc9changes autour des cinq strat\xe9gies sur l’or. Lecture des performances pass\xe9es des simulations, pas de conseil.",en:"Exchanges around the five gold strategies. Reading past performance of the simulations, no advice."}},autonomie:{nom:{fr:"Autonomie",en:"Autonomy"},desc:{fr:"Le fil autour de l’autonomie, du protocole \xe0 la vie hors ligne. Le pont Otarkych.",en:"The thread on autonomy, from the protocol to life offline. The Otarkych bridge."}},"cercle-argent":{nom:{fr:"Cercle",en:"Circle"},desc:{fr:"R\xe9serv\xe9 aux Pass Argent et au-dessus. Discussions plus avanc\xe9es sur la m\xe9canique du protocole.",en:"Reserved for Silver Pass and above. More advanced discussions on the mechanics of the protocol."}},"cercle-or":{nom:{fr:"Cercle Or",en:"Gold Circle"},desc:{fr:"R\xe9serv\xe9 aux Pass Or et Diamant. Retours rapproch\xe9s et priorit\xe9s produit.",en:"Reserved for Gold and Diamond Pass. Close feedback and product priorities."}}}}}]);